// Minimal Pixel Dodger game targeting <canvas id="game"></canvas>
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const W = canvas.width;
  const H = canvas.height;

  // Player (square)
  const player = {
    x: 50,
    y: H - 30,
    w: 20,
    h: 20,
    vy: 0,
    onGround: true,
  };
  const GRAVITY = 0.6;
  const JUMP_VELOCITY = -12;

  // Obstacles (spikes/gaps implemented as rectangles)
  const obstacles = [];
  let obstacleTimer = 0;
  const OBSTACLE_INTERVAL = 90; // frames
  let speed = 3;
  let speedIncrement = 0.001;
  let score = 0;
  let gameOver = false;

  function spawnObstacle() {
    const size = 20 + Math.random() * 20; // varied width/height
    const gap = Math.random() < 0.2; // 20% chance of gap (no obstacle, just a hole)
    if (!gap) {
      obstacles.push({
        x: W,
        y: H - size,
        w: size,
        h: size,
      });
    }
  }

  function update() {
    if (gameOver) return;
    // player physics
    player.vy += GRAVITY;
    player.y += player.vy;
    if (player.y + player.h >= H) {
      player.y = H - player.h;
      player.vy = 0;
      player.onGround = true;
    } else {
      player.onGround = false;
    }

    // obstacles movement
    for (let i = obstacles.length - 1; i >= 0; i--) {
      const o = obstacles[i];
      o.x -= speed;
      if (o.x + o.w < 0) obstacles.splice(i, 1);
    }

    // spawn logic
    if (obstacleTimer-- <= 0) {
      spawnObstacle();
      obstacleTimer = OBSTACLE_INTERVAL - Math.random() * 30;
    }

    // collision detection
    for (const o of obstacles) {
      if (
        player.x < o.x + o.w &&
        player.x + player.w > o.x &&
        player.y < o.y + o.h &&
        player.y + player.h > o.y
      ) {
        gameOver = true;
        break;
      }
    }

    // speed & score progression
    speed += speedIncrement;
    score++;
  }

  function draw() {
    ctx.clearRect(0, 0, W, H);
    // player
    ctx.fillStyle = '#0a0';
    ctx.fillRect(player.x, player.y, player.w, player.h);
    // obstacles
    ctx.fillStyle = '#a00';
    for (const o of obstacles) {
      ctx.fillRect(o.x, o.y, o.w, o.h);
    }
    // score
    ctx.fillStyle = '#000';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + score, 10, 20);
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0, 0, W, H);
      ctx.fillStyle = '#fff';
      ctx.textAlign = 'center';
      ctx.font = '24px sans-serif';
      ctx.fillText('Game Over', W / 2, H / 2);
      ctx.font = '16px sans-serif';
      ctx.fillText('Click to restart', W / 2, H / 2 + 30);
    }
  }

  function loop() {
    update();
    draw();
    requestAnimationFrame(loop);
  }

  // input handling
  window.addEventListener('keydown', (e) => {
    if (e.code === 'Space' && player.onGround && !gameOver) {
      player.vy = JUMP_VELOCITY;
      player.onGround = false;
    }
  });
  canvas.addEventListener('click', () => {
    if (gameOver) {
      // reset state
      obstacles.length = 0;
      player.y = H - player.h;
      player.vy = 0;
      player.onGround = true;
      speed = 3;
      score = 0;
      gameOver = false;
      obstacleTimer = 0;
    }
  });

  // start loop
  requestAnimationFrame(loop);
})();
